SELECT
    b.market_date,
    COUNT(pr.id) AS saved_records,
    CASE
        WHEN b.file_hash <> '254b8e735179aea9bf6c03168414a164f65857e73948799c31448ab104052e32'
            THEN 'CONFLICTO: existe otro PDF para esta fecha'
        WHEN COUNT(pr.id) <> 53
            THEN 'ERROR: cantidad de registros inesperada'
        ELSE 'OK'
    END AS import_status
FROM bulletins AS b
LEFT JOIN prices AS pr
    ON pr.bulletin_id = b.id
WHERE b.market_date = '2026-10-06'
GROUP BY b.id, b.market_date, b.file_hash;
